/**
 * Provenance for the archival frames in public/archive/.
 * Generated by scripts/fetch-archive.mjs — do not edit by hand.
 *
 * All frames are NASA public-domain imagery. Run `npm run archive` to populate
 * this file and download the frames; until then the interface renders each
 * plate as an empty archival sleeve, which is a designed state rather than a
 * broken one.
 */

export interface ArchiveCredit {
  title: string
  nasaId: string
  center: string
  date: string
}

export const ARCHIVE_CREDITS: Record<string, ArchiveCredit> = {}
